FeatureScript 3083;
import(path : "onshape/std/common.fs", version : "3083.0");

// Generated by fsgen (paste export). Paste into a Feature Studio, then add the feature
// to a Part Studio from the toolbar. Parameters appear in the feature dialog.

// Midpoint of an arc from its endpoints; k = tan(sweep / 4) keeps the arc's sweep when parameters change.
function arcMid(a is Vector, b is Vector, k is number) returns Vector
{
    var d = b - a;
    return (a + b) / 2 + vector(d[1], -d[0]) * (k / 2);
}

annotation { "Feature Type Name" : "Auger" }
export const auger = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Tube length" }
        isLength(definition.tubeLength, { (millimeter) : [0, 250, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Tube diameter" }
        isLength(definition.tubeDiameter, { (millimeter) : [0, 25, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Wall thickness" }
        isLength(definition.wallThickness, { (millimeter) : [0, 2, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Funnel length" }
        isLength(definition.funnelLength, { (millimeter) : [0, 12, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Outlet diameter" }
        isLength(definition.outletDiameter, { (millimeter) : [0, 3, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Core diameter" }
        isLength(definition.coreDiameter, { (millimeter) : [0, 8, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Core tip diameter" }
        isLength(definition.coreTipDiameter, { (millimeter) : [0, 0.8, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Flight pitch" }
        isLength(definition.flightPitch, { (millimeter) : [0, 10.41625, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Flight turns" }
        isInteger(definition.flightTurns, { (unitless) : [0, 8, 10000] } as IntegerBoundSpec);
        annotation { "Name" : "Flight thickness" }
        isLength(definition.flightThickness, { (millimeter) : [0, 0.5, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Gear center" }
        isLength(definition.gearCenter, { (millimeter) : [0, 83.333, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Gear width" }
        isLength(definition.gearWidth, { (millimeter) : [0, 10, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Thread length" }
        isLength(definition.threadLength, { (millimeter) : [0, 25, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Thread pitch" }
        isLength(definition.threadPitch, { (millimeter) : [0, 3.5, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Thread major diameter" }
        isLength(definition.threadMajorDiameter, { (millimeter) : [0, 26, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Thread minor diameter" }
        isLength(definition.threadMinorDiameter, { (millimeter) : [0, 23, 10000] } as LengthBoundSpec);
    }
    {
    // Core sketch
    var coreSketchSk = newSketchOnPlane(context, id + "coreSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(coreSketchSk, "core_0", { "start" : vector(0, 0) * millimeter, "end" : vector(definition.coreTipDiameter / 2, (0 * millimeter)) });
    skLineSegment(coreSketchSk, "core_1", { "start" : vector(definition.coreTipDiameter / 2, (0 * millimeter)), "end" : vector(definition.coreDiameter / 2, definition.funnelLength) });
    skLineSegment(coreSketchSk, "core_2", { "start" : vector(definition.coreDiameter / 2, definition.funnelLength), "end" : vector(definition.coreDiameter / 2, definition.flightPitch * definition.flightTurns) });
    skLineSegment(coreSketchSk, "core_3", { "start" : vector(definition.coreDiameter / 2, definition.flightPitch * definition.flightTurns), "end" : vector((0 * millimeter), definition.flightPitch * definition.flightTurns) });
    skLineSegment(coreSketchSk, "core_4", { "start" : vector((0 * millimeter), definition.flightPitch * definition.flightTurns), "end" : vector(0, 0) * millimeter });
    skLineSegment(coreSketchSk, "axis", { "start" : vector(0, 0) * millimeter, "end" : vector(0, 10) * millimeter, "construction" : true });
    skSolve(coreSketchSk);
    // Core
    opRevolve(context, id + "core" + "tool", { "entities" : qSketchRegion(id + "coreSketch"), "axis" : line(vector(0, 0, 0) * millimeter, vector(0, 0, 1)), "angleForward" : 360 * degree });
    // Flight helix sketch
    var flightHelixSketchSk = newSketchOnPlane(context, id + "flightHelixSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(flightHelixSketchSk, "circle", { "center" : vector(0, 0) * millimeter, "radius" : definition.coreDiameter / 2 });
    skSolve(flightHelixSketchSk);
    // Flight helix
    const hFlightHelixCircle = evCurveDefinition(context, { "edge" : sketchEntityQuery(id + "flightHelixSketch", EntityType.EDGE, "circle") });
    opHelix(context, id + "flightHelix", { "direction" : hFlightHelixCircle.coordSystem.zAxis, "axisStart" : hFlightHelixCircle.coordSystem.origin, "startPoint" : hFlightHelixCircle.coordSystem.origin + (hFlightHelixCircle.radius) * hFlightHelixCircle.coordSystem.xAxis, "interval" : [0, definition.flightTurns], "clockwise" : true, "helicalPitch" : definition.flightPitch, "spiralPitch" : 0 * meter });
    // Flight profile
    var flightProfileSk = newSketchOnPlane(context, id + "flightProfile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(flightProfileSk, "blade_bottom", { "start" : vector(definition.coreTipDiameter / 2, (0 * millimeter)), "end" : vector(definition.tubeDiameter / 2 - definition.wallThickness + (0.5 * millimeter), (0 * millimeter)) });
    skLineSegment(flightProfileSk, "blade_right", { "start" : vector(definition.tubeDiameter / 2 - definition.wallThickness + (0.5 * millimeter), (0 * millimeter)), "end" : vector(definition.tubeDiameter / 2 - definition.wallThickness + (0.5 * millimeter), definition.flightThickness) });
    skLineSegment(flightProfileSk, "blade_top", { "start" : vector(definition.tubeDiameter / 2 - definition.wallThickness + (0.5 * millimeter), definition.flightThickness), "end" : vector(definition.coreTipDiameter / 2, definition.flightThickness) });
    skLineSegment(flightProfileSk, "blade_left", { "start" : vector(definition.coreTipDiameter / 2, definition.flightThickness), "end" : vector(definition.coreTipDiameter / 2, (0 * millimeter)) });
    skSolve(flightProfileSk);
    // Flight
    opSweep(context, id + "flight" + "tool", { "profiles" : qSketchRegion(id + "flightProfile"), "path" : qCreatedBy(id + "flightHelix", EntityType.EDGE) });
    opBoolean(context, id + "flight" + "bool", { "tools" : qUnion([qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), qCreatedBy(id + "flight" + "tool", EntityType.BODY)), qCreatedBy(id + "flight" + "tool", EntityType.BODY)]), "operationType" : BooleanOperationType.UNION });
    // Tube sketch
    var tubeSketchSk = newSketchOnPlane(context, id + "tubeSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(tubeSketchSk, "wall_0", { "start" : vector(definition.outletDiameter / 2, (0 * millimeter)), "end" : vector(definition.tubeDiameter / 2, (0 * millimeter)) });
    skLineSegment(tubeSketchSk, "wall_1", { "start" : vector(definition.tubeDiameter / 2, (0 * millimeter)), "end" : vector(definition.tubeDiameter / 2, definition.tubeLength - definition.threadLength) });
    skLineSegment(tubeSketchSk, "wall_2", { "start" : vector(definition.tubeDiameter / 2, definition.tubeLength - definition.threadLength), "end" : vector(definition.threadMinorDiameter / 2, definition.tubeLength - definition.threadLength) });
    skLineSegment(tubeSketchSk, "wall_3", { "start" : vector(definition.threadMinorDiameter / 2, definition.tubeLength - definition.threadLength), "end" : vector(definition.threadMinorDiameter / 2, definition.tubeLength) });
    skLineSegment(tubeSketchSk, "wall_4", { "start" : vector(definition.threadMinorDiameter / 2, definition.tubeLength), "end" : vector(definition.tubeDiameter / 2 - definition.wallThickness, definition.tubeLength) });
    skLineSegment(tubeSketchSk, "wall_5", { "start" : vector(definition.tubeDiameter / 2 - definition.wallThickness, definition.tubeLength), "end" : vector(definition.tubeDiameter / 2 - definition.wallThickness, definition.funnelLength) });
    skLineSegment(tubeSketchSk, "wall_6", { "start" : vector(definition.tubeDiameter / 2 - definition.wallThickness, definition.funnelLength), "end" : vector(definition.outletDiameter / 2, (0 * millimeter)) });
    skSolve(tubeSketchSk);
    // Tube
