    opBoolean(context, id + "tube" + "bool", { "tools" : qUnion([qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), qCreatedBy(id + "tube" + "tool", EntityType.BODY)), qCreatedBy(id + "tube" + "tool", EntityType.BODY)]), "operationType" : BooleanOperationType.UNION });
    // Gear plane
    // Gear blank sketch
    var gearBlankSketchSk = newSketchOnPlane(context, id + "gearBlankSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter + (definition.gearCenter - (definition.gearWidth / 2)) * vector(0, 0, 1), vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(gearBlankSketchSk, "tip", { "center" : vector(0, 0) * millimeter, "radius" : (23 * millimeter) });
    skCircle(gearBlankSketchSk, "hub", { "center" : vector(0, 0) * millimeter, "radius" : definition.tubeDiameter / 2 - (0.5 * millimeter) });
    skSolve(gearBlankSketchSk);
    // Gear blank
    opExtrude(context, id + "gearBlank" + "tool", { "entities" : qSketchRegion(id + "gearBlankSketch", true), "direction" : vector(0, 0, 1), "endBound" : BoundingType.BLIND, "endDepth" : definition.gearWidth });
    opBoolean(context, id + "gearBlank" + "bool", { "tools" : qUnion([qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), qCreatedBy(id + "gearBlank" + "tool", EntityType.BODY)), qCreatedBy(id + "gearBlank" + "tool", EntityType.BODY)]), "operationType" : BooleanOperationType.UNION });
    // Tooth gap sketch
    var toothGapSketchSk = newSketchOnPlane(context, id + "toothGapSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter + (definition.gearCenter - (definition.gearWidth / 2)) * vector(0, 0, 1), vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(toothGapSketchSk, "flankA", { "start" : vector(23.49962902, 0.132044685) * millimeter, "mid" : arcMid(vector(23.49962902, 0.132044685) * millimeter, vector(21.2012601, 0.987633599) * millimeter, 0.07611107969), "end" : vector(21.2012601, 0.987633599) * millimeter });
    skArc(toothGapSketchSk, "filletA", { "start" : vector(21.2012601, 0.987633599) * millimeter, "mid" : arcMid(vector(21.2012601, 0.987633599) * millimeter, vector(20.79286873, 1.444734874) * millimeter, -0.3424169138), "end" : vector(20.79286873, 1.444734874) * millimeter });
    skArc(toothGapSketchSk, "rootLand", { "start" : vector(20.79286873, 1.444734874) * millimeter, "mid" : arcMid(vector(20.79286873, 1.444734874) * millimeter, vector(20.78683452, 1.529104195) * millimeter, 0.00101455039), "end" : vector(20.78683452, 1.529104195) * millimeter });
    skArc(toothGapSketchSk, "filletB", { "start" : vector(20.78683452, 1.529104195) * millimeter, "mid" : arcMid(vector(20.78683452, 1.529104195) * millimeter, vector(21.12601676, 2.039672989) * millimeter, -0.3424169124), "end" : vector(21.12601676, 2.039672989) * millimeter });
    skArc(toothGapSketchSk, "flankB", { "start" : vector(21.12601676, 2.039672989) * millimeter, "mid" : arcMid(vector(21.12601676, 2.039672989) * millimeter, vector(23.2792286, 3.213645243) * millimeter, 0.07611107968), "end" : vector(23.2792286, 3.213645243) * millimeter });
    skLineSegment(toothGapSketchSk, "outside", { "start" : vector(23.2792286, 3.213645243) * millimeter, "end" : vector(23.49962902, 0.132044685) * millimeter });
    skSolve(toothGapSketchSk);
    // Tooth gap
    opExtrude(context, id + "toothGap" + "tool", { "entities" : qSketchRegion(id + "toothGapSketch"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.THROUGH_ALL });
    opBoolean(context, id + "toothGap" + "bool", { "tools" : qCreatedBy(id + "toothGap" + "tool", EntityType.BODY), "targets" : qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), qCreatedBy(id + "toothGap" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // Gear teeth
    for (var k0_0_0 = 1; k0_0_0 < 44; k0_0_0 += 1)
    {
        opExtrude(context, id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "tool", { "entities" : qSketchRegion(id + "toothGapSketch"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.THROUGH_ALL });
        opTransform(context, id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "move", { "bodies" : qCreatedBy(id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "tool", EntityType.BODY), "transform" : rotationAround(line(vector(0, 0, 0) * millimeter, vector(0, 0, 1)), k0_0_0 * ((360 * degree)) / (44)) });
        opBoolean(context, id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "bool", { "tools" : qCreatedBy(id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "tool", EntityType.BODY), "targets" : qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), qCreatedBy(id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    }
    // Thread plane
    // Thread helix sketch
    var threadHelixSketchSk = newSketchOnPlane(context, id + "threadHelixSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter + (definition.tubeLength - definition.threadLength - (1.65 * millimeter)) * vector(0, 0, 1), vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(threadHelixSketchSk, "circle", { "center" : vector(0, 0) * millimeter, "radius" : definition.threadMinorDiameter / 2 });
    skSolve(threadHelixSketchSk);
    // Thread helix
    const hThreadHelixCircle = evCurveDefinition(context, { "edge" : sketchEntityQuery(id + "threadHelixSketch", EntityType.EDGE, "circle") });
    opHelix(context, id + "threadHelix", { "direction" : hThreadHelixCircle.coordSystem.zAxis, "axisStart" : hThreadHelixCircle.coordSystem.origin, "startPoint" : hThreadHelixCircle.coordSystem.origin + (hThreadHelixCircle.radius) * hThreadHelixCircle.coordSystem.xAxis, "interval" : [0, (definition.threadLength + (3 * millimeter)) / definition.threadPitch], "clockwise" : true, "helicalPitch" : definition.threadPitch, "spiralPitch" : 0 * meter });
    // Thread profile
    var threadProfileSk = newSketchOnPlane(context, id + "threadProfile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(threadProfileSk, "lowerFlank", { "start" : vector(definition.threadMinorDiameter / 2 - (0.5 * millimeter), definition.tubeLength - definition.threadLength - (1.65 * millimeter) - (1.083333 * millimeter)), "end" : vector(definition.threadMajorDiameter / 2 - (0.417797 * millimeter), definition.tubeLength - definition.threadLength - (1.65 * millimeter) - (0.819634 * millimeter)) });
    skArc(threadProfileSk, "lowerRound", { "start" : vector(definition.threadMajorDiameter / 2 - (0.417797 * millimeter), definition.tubeLength - definition.threadLength - (1.65 * millimeter) - (0.819634 * millimeter)), "mid" : arcMid(vector(definition.threadMajorDiameter / 2 - (0.417797 * millimeter), definition.tubeLength - definition.threadLength - (1.65 * millimeter) - (0.819634 * millimeter)), vector(definition.threadMajorDiameter / 2, definition.tubeLength - definition.threadLength - (1.65 * millimeter) - (0.326438 * millimeter)), 0.366616292), "end" : vector(definition.threadMajorDiameter / 2, definition.tubeLength - definition.threadLength - (1.65 * millimeter) - (0.326438 * millimeter)) });
    skLineSegment(threadProfileSk, "crest", { "start" : vector(definition.threadMajorDiameter / 2, definition.tubeLength - definition.threadLength - (1.65 * millimeter) - (0.326438 * millimeter)), "end" : vector(definition.threadMajorDiameter / 2, definition.tubeLength - definition.threadLength - (1.65 * millimeter) + (0.326438 * millimeter)) });
    skArc(threadProfileSk, "upperRound", { "start" : vector(definition.threadMajorDiameter / 2, definition.tubeLength - definition.threadLength - (1.65 * millimeter) + (0.326438 * millimeter)), "mid" : arcMid(vector(definition.threadMajorDiameter / 2, definition.tubeLength - definition.threadLength - (1.65 * millimeter) + (0.326438 * millimeter)), vector(definition.threadMajorDiameter / 2 - (0.417797 * millimeter), definition.tubeLength - definition.threadLength - (1.65 * millimeter) + (0.819634 * millimeter)), 0.366616292), "end" : vector(definition.threadMajorDiameter / 2 - (0.417797 * millimeter), definition.tubeLength - definition.threadLength - (1.65 * millimeter) + (0.819634 * millimeter)) });
    skLineSegment(threadProfileSk, "upperFlank", { "start" : vector(definition.threadMajorDiameter / 2 - (0.417797 * millimeter), definition.tubeLength - definition.threadLength - (1.65 * millimeter) + (0.819634 * millimeter)), "end" : vector(definition.threadMinorDiameter / 2 - (0.5 * millimeter), definition.tubeLength - definition.threadLength - (1.65 * millimeter) + (1.083333 * millimeter)) });
    skLineSegment(threadProfileSk, "root", { "start" : vector(definition.threadMinorDiameter / 2 - (0.5 * millimeter), definition.tubeLength - definition.threadLength - (1.65 * millimeter) + (1.083333 * millimeter)), "end" : vector(definition.threadMinorDiameter / 2 - (0.5 * millimeter), definition.tubeLength - definition.threadLength - (1.65 * millimeter) - (1.083333 * millimeter)) });
    skSolve(threadProfileSk);
    // Thread
