    // Thread trim sketch
    var threadTrimSketchSk = newSketchOnPlane(context, id + "threadTrimSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(threadTrimSketchSk, "overrun_bottom", { "start" : vector(definition.tubeDiameter / 2 - definition.wallThickness, definition.tubeLength), "end" : vector(definition.threadMajorDiameter / 2 + (1 * millimeter), definition.tubeLength) });
    skLineSegment(threadTrimSketchSk, "overrun_right", { "start" : vector(definition.threadMajorDiameter / 2 + (1 * millimeter), definition.tubeLength), "end" : vector(definition.threadMajorDiameter / 2 + (1 * millimeter), definition.tubeLength + 2 * definition.threadPitch) });
    skLineSegment(threadTrimSketchSk, "overrun_top", { "start" : vector(definition.threadMajorDiameter / 2 + (1 * millimeter), definition.tubeLength + 2 * definition.threadPitch), "end" : vector(definition.tubeDiameter / 2 - definition.wallThickness, definition.tubeLength + 2 * definition.threadPitch) });
    skLineSegment(threadTrimSketchSk, "overrun_left", { "start" : vector(definition.tubeDiameter / 2 - definition.wallThickness, definition.tubeLength + 2 * definition.threadPitch), "end" : vector(definition.tubeDiameter / 2 - definition.wallThickness, definition.tubeLength) });
    skSolve(threadTrimSketchSk);
    // Thread trim
