    // remove the construction sketches and curves
    opDeleteBodies(context, id + "cleanupSketches", { "entities" : qUnion([qCreatedBy(id + "coreSketch", EntityType.BODY), qCreatedBy(id + "flightHelixSketch", EntityType.BODY), qCreatedBy(id + "flightHelix", EntityType.BODY), qCreatedBy(id + "flightProfile", EntityType.BODY), qCreatedBy(id + "tubeSketch", EntityType.BODY), qCreatedBy(id + "gearBlankSketch", EntityType.BODY), qCreatedBy(id + "toothGapSketch", EntityType.BODY), qCreatedBy(id + "threadHelixSketch", EntityType.BODY), qCreatedBy(id + "threadHelix", EntityType.BODY), qCreatedBy(id + "threadProfile", EntityType.BODY), qCreatedBy(id + "threadTrimSketch", EntityType.BODY)]) });
